export enum CodeLanguage {
  Python = 'python',
  Curl = 'curl',
  JavaScript = 'javascript',
}

export enum CatalogDetailsTab {
  /** Description content (`item.description`). Always the first tab. */
  About = 'about',
  /** Read-only long-form text body, e.g. a prompt's content. */
  Content = 'content',
  Overview = 'overview',
  Pricing = 'pricing',
  /** Runtime usage-limit progress for model deployments. */
  Limits = 'limits',
  /** Resource ID, endpoint, and code snippets. Labeled "Connect". */
  Api = 'api',
  /** Tool definitions tab, shown for Toolset entities. */
  Tools = 'tools',
}

export enum CatalogLimitStatus {
  /** At least one capped row is at or above 75% usage, none has reached its limit. */
  RunningLow = 'runningLow',
  /** At least one capped row has reached (or exceeded) its limit. */
  LimitReached = 'limitReached',
}

export enum DetailsConfirmationKind {
  /** Owner-side deletion of the item for everyone. */
  Delete = 'delete',
  /** Signing out of the item's stored credentials. */
  Logout = 'logout',
  /** Recipient-side removal of the caller's own shared access. */
  Unshare = 'unshare',
  /** Owner-side revocation of everyone else's shared access. */
  RevokeAccess = 'revokeAccess',
  /** Removing a configured API key from a credentials slot. */
  DeleteApiKey = 'deleteApiKey',
  /**
   * Owner-side request to remove an already-published copy from one folder.
   * The source item survives untouched, and the removal itself takes effect
   * only after an administrator approves the request — copy for this kind
   * describes a request, never a completed removal.
   */
  Unpublish = 'unpublish',
}

export enum DetailsConfirmationVariant {
  /** Irreversible loss for everyone — red identity card and a danger confirm button. */
  Danger = 'danger',
  /** Affects only the current user and is recoverable — blue identity card and a neutral confirm button. */
  Info = 'info',
}

export enum DeploymentSize {
  SM = 'sm',
  LG = 'lg',
}

export enum CatalogViewMode {
  Grid = 'grid',
  Cards = 'cards',
}

export enum CatalogContentNodeType {
  File = 'file',
  Folder = 'folder',
}

export enum CatalogContentPreviewType {
  Markdown = 'markdown',
  Text = 'text',
  Image = 'image',
  Unsupported = 'unsupported',
}

export interface CatalogEmptyStateContext {
  /** Current search query text. */
  query: string;
  /** Currently active entity-type tab id, or `''` when no tab is active. */
  activeTab: string;
  /** Whether at least one Topics filter value is currently selected. */
  hasTopicFilters: boolean;
  /** Current state of the "My Apps" filter toggle. */
  isMyAppsActive: boolean;
}

export interface CatalogProps {
  /**
   * Items to display in the Browse section's grid/list. Also drives the
   * default entity-type tabs and Topics filter options when `tabs`/
   * `topicOptions` are omitted.
   */
  items: CatalogItem[];
  /**
   * Externally-controlled entity-type tab list. When omitted, `Catalog`
   * derives tabs internally from `items` via `buildCatalogTabs`. Fewer than
   * two tabs renders no tab row.
   *
   * Lets a host compute tabs from a wider item set than `items` — e.g. so a
   * host that narrows `items` for grid display (by a category-tree
   * selection) doesn't lose a tab for a type with zero matches in that
   * narrowed set.
   */
  tabs?: TabModel[];
  /**
   * Externally-controlled set of available Topics filter options. When
   * omitted, `Catalog` derives them internally from `items` via
   * `getTopicOptions`.
   *
   * Lets a host compute the option set from a wider item set than `items`,
   * for the same reason as `tabs`.
   */
  topicOptions?: Set<string>;
  /** Items to display in the Favorites section. */
  favorites: CatalogItem[];
  /** Grouped text labels for headings and actions. */
  titles?: CatalogTitles;
  /**
   * Renders in place of the Browse section's heading (`titles.browseTitle`)
   * when supplied, e.g. so a host can render a clickable breadcrumb instead
   * of a plain text label. The item count normally shown next to the heading
   * is not rendered alongside it — include it in the supplied node if needed.
   */
  browseHeaderRenderer?: ReactNode;
  /** Whether catalog data is loading (reserved for future loading state). */
  isLoading?: boolean;
  /** Error to display if data loading failed (reserved for future error state). */
  error?: Error | null;
  /** Called when any item's star is toggled. */
  onToggleFavorite?: (id: string, isStarred: boolean) => void;
  /**
   * Additional caller-supplied rule for whether the favorite star is shown for
   * an item, in the browse grid, the list view, the favorites strip, and the
   * details panel. Returning `false` hides the star everywhere and makes the
   * item non-favoritable. Defaults to **visible** when omitted, so a predicate
   * can only ever narrow visibility, never widen it.
   */
  isFavoriteVisible?: (item: CatalogItem) => boolean;
  /**
   * Per-column overrides for whether an optional `ListView` column (`folder`,
   * `tags`, `favorite`) renders for the active tab, given its entity type.
   * Independent of `isFavoriteVisible` (which only gates the star on
   * individual rows, in the browse grid and cards too, not the column).
   * Replaces that column's built-in default rule — e.g. `folder` normally
   * hides for `CatalogEntityType.Model`; columns omitted from this map keep
   * their default. `favorite` is additionally combined (AND) with
   * `isReadonly`. No effect on the Browse grid/cards, only the list view's
   * table.
   */
  columnVisibility?: ListViewColumnVisibility;
  /** Called when the "Use in chat" button is clicked in the details panel. */
  onUseInChat?: (item: CatalogItem) => void;
  /** Controls whether the primary action button is shown for an item. */
  isPrimaryActionVisible?: (item: CatalogItem) => boolean;
  /** Called when the "Share" button is clicked in the details panel. */
  onShare?: (item: CatalogItem) => void;
  /** Controls whether the "Publish" action is shown for an item. */
  isPublishVisible?: (item: CatalogItem) => boolean;
  /**
   * Resolves whether whichever of "Publish"/"Unpublish" applies renders as its
   * own button in the details header rather than an entry in its "Manage"
   * menu. Defaults to `false` — the menu entry.
   */
  isPublishPrimary?: (item: CatalogItem) => boolean;
  /** Resolves previously published versions for an item, most recent first. */
  getPublishHistory?: (item: CatalogItem) => Promise<PublishHistoryEntry[]>;
  /** Root-level destination folder nodes offered by the publish flow. */
  publishFolderItems?: PublishFolderNode[];
  /**
   * Externally-controlled set of expanded publish-folder path keys
   * (`path.join('/')`). Pass this together with `onPublishExpandedPathsChange`
   * when the host lazily fetches a folder's children on expand.
   */
  publishExpandedPaths?: Set<string>;
  /** Called when the set of expanded publish folders changes; required to control `publishExpandedPaths`. */
  onPublishExpandedPathsChange?: (paths: Set<string>) => void;
  /** Publish-folder path keys currently being fetched by the host. */
  publishLoadingPaths?: Set<string>;
  /** Resolves whether the current user can publish to a given folder path. */
  hasPublishWriteAccess?: (folderPath: string[]) => boolean;
  /**
   * Initial value for the publish flow's display-author field, and the value
   * it returns to on reset. Resolved by the host from the signed-in user's
   * display name; the catalog library holds no notion of a session.
   */
  publishDefaultAuthor?: string;
  /**
   * Called with the destination folder path, current access rules, trimmed
   * display author, and the credentials opt-in when the user confirms
   * publish/update. The fifth argument is additive — a callback declaring only
   * the first four parameters stays assignable.
   */
  onPublish?: (
    item: CatalogItem,
    folderPath: string[],
    rules: PublicationRule[],
    author: string,
    publishCredentials: boolean,
  ) => Promise<void>;
  /** Called after a successful publish; use this to surface a success notification. */
  onPublishSuccess?: (item: CatalogItem, folderPath: string[]) => void;
  /** Called with the rejection reason when a publish request fails; use this to surface an error notification. */
  onPublishError?: (
    item: CatalogItem,
    folderPath: string[],
    error: unknown,
  ) => void;
  /** Called when the user confirms a new folder name in the publish flow. */
  onCreatePublishFolder?: (parentPath: string[], name: string) => void;
  /** Text overrides forwarded to the publish flow. */
  publishLabels?: PublishPanelLabels & PublishFooterLabels;
  /** Options offered in the access-rules editor's source picker. Defaults to `[]` when absent. */
  ruleSourceOptions?: string[];
  /**
   * Resolves the access rules already configured for a destination folder,
   * called whenever the selected folder changes. The result fully replaces
   * the rules editor's contents. Omit to skip pre-filling entirely.
   */
  onFetchExistingRules?: (folderPath: string[]) => Promise<PublicationRule[]>;
  /** Called when the "Edit" button is clicked in the details panel. Shown only when the item's `isEditable` is `true`. */
  onEdit?: (item: CatalogItem) => void;
  /**
   * Called when the "Download" action is clicked in the details panel, with no
   * confirmation step. When "Download" renders in the Manage menu (see
   * `isDownloadPrimary`), the panel does not await the result or show a
   * pending state, so the host owns any progress and failure feedback. When
   * "Download" is the primary action, the panel awaits this call and shows a
   * pending/disabled state for its duration.
   */
  onDownload?: (item: CatalogItem) => Promise<void> | void;
  /**
   * Narrows which items offer the "Download" action. Defaults to `true`
   * (visible for every item) whenever `onDownload` is supplied.
   */
  isDownloadVisible?: (item: CatalogItem) => boolean;
  /**
   * Resolves whether an item's Download action renders as the primary action
   * instead of a Manage-menu entry. Defaults to
   * `item.type === CatalogEntityType.Skill`.
   */
  isDownloadPrimary?: (item: CatalogItem) => boolean;
  /**
   * Resolves the text of a file picked in the details panel's Content tab,
   * given its opaque `id`. The panel shows a loading state while it is
   * pending and renders the resolved text as the body. Superseded by
   * `onLoadContentFilePreview` for a given pick when both are supplied.
   */
  onLoadContentFile?: (fileId: string) => Promise<string | undefined>;
  /**
   * Resolves a picked file's typed preview, given its opaque `id`. Takes
   * precedence over `onLoadContentFile` when both are supplied.
   */
  onLoadContentFilePreview?: (
    fileId: string,
  ) => Promise<CatalogContentFilePreview | undefined>;
  /**
   * Renders a picked file through a host-owned preview surface. Takes
   * precedence over both loading callbacks, while the catalog continues to
   * own selection and passes the opaque file id and resolved basename only.
   */
  renderContentFilePreview?: (fileId: string, fileName: string) => ReactNode;
  /**
   * Called immediately when the "Delete" button in the details panel is
   * clicked, with no confirmation step. Shown only when the item's `isMyApp`
   * is `true` and its `type` is `Application` or `Toolset`. May return a
   * promise; the button shows a disabled state while pending.
   */
  onDelete?: (item: CatalogItem) => Promise<void> | void;
  /**
   * Called when removal is confirmed via the details panel's confirmation
   * popup, for an item shared with the current user (`sharedWithMe: true`).
   * May return a promise; the popup shows a loading state and prevents
   * duplicate submission while pending.
   */
  onUnshare?: (item: CatalogItem) => Promise<void> | void;
  /**
   * Narrows where the "Remove from My List" action is offered, on top of the
   * built-in `sharedWithMe`/`isMyApp` rule. Use it to declare that unsharing
   * is unsupported for a kind of item. Defaults to `true` (visible) when
   * absent.
   */
  isUnshareVisible?: (item: CatalogItem) => boolean;
  /**
   * Called when revocation is confirmed via the details panel's confirmation
   * step, for an item the current user owns (`isMyApp: true`), removing every
   * recipient's shared access at once. May return a promise; the confirmation
   * shows a loading state and prevents duplicate submission while pending.
   */
  onRevokeShare?: (item: CatalogItem) => Promise<void> | void;
  /**
   * Resolves how many users currently hold shared access to an owned item.
   * Called when the owner opens the details panel's Manage menu, so "Revoke
   * access" is gated and labelled on a count that is never stale. `0` hides
   * the action; `undefined` (or a rejection) leaves it reachable without a
   * count. Omit to offer the action for every owned item.
   */
  onFetchRecipientsCount?: (item: CatalogItem) => Promise<number | undefined>;
  /**
   * Narrows where the "Revoke access" action is offered, on top of the
   * built-in `isMyApp` rule and the recipient count. Use it to declare that
   * revoking is unsupported for a kind of item. Defaults to `true` (visible)
   * when absent.
   */
  isRevokeShareVisible?: (item: CatalogItem) => boolean;
  /**
   * Called when unpublish is confirmed via the details panel's confirmation
   * step, with the published folder's path segments. May return a promise;
   * the confirmation shows a loading state and prevents duplicate submission
   * while pending. The published copy survives until an administrator
   * approves, so the panel stays open and the item stays visible.
   */
  onUnpublish?: (
    item: CatalogItem,
    folderPath: string[],
  ) => Promise<void> | void;
  /**
   * Narrows where the "Unpublish" action is offered, on top of the presence
   * of `onUnpublish` and at least one resolved `getPublishHistory` entry.
   * Defaults to `true` (visible) when absent.
   */
  isUnpublishVisible?: (item: CatalogItem) => boolean;
  /**
   * Renders the Share popover content anchored to the Share button in the
   * details panel. When provided, clicking Share opens this popover instead
   * of calling `onShare`.
   */
  shareOverlay?: (item: CatalogItem, onClose: () => void) => ReactNode;
  /**
   * Additional caller-supplied rule for whether the "Share" action is shown
   * for the item, combined (AND) with the built-in ownership/type rule.
   * Absent means the built-in rule alone decides.
   */
  isShareVisible?: (item: CatalogItem) => boolean;
  /**
   * Resolves whether "Share" renders as its own button in the details header
   * rather than an entry in its "Manage" menu. Defaults to `true` — the
   * button. Returning `false` moves it into the menu, beside "Delete".
   */
  isSharePrimary?: (item: CatalogItem) => boolean;
  /**
   * Called when the credentials login form is submitted in the details
   * panel, for the given credentials `level` (`USER` or `GLOBAL`). May
   * return a promise; awaited before refreshing via `onFetchDetails`.
   */
  onLogin?: (
    item: CatalogItem,
    params: { level: CredentialsLevel; apiKey?: string },
  ) => Promise<void> | void;
  /**
   * Called when logout is confirmed in the details panel's credentials
   * section, for the given credentials `level`. May return a promise;
   * awaited before refreshing via `onFetchDetails`.
   */
  onLogout?: (
    item: CatalogItem,
    params: { level: CredentialsLevel },
  ) => Promise<void> | void;
  /**
   * Called when the details panel opens for an item. Use this to fetch
   * structured tab data (Overview/Pricing/API/Tools) from an API and pass it
   * back. The resolved data takes precedence over the item's static `details`
   * field for the currently open item. Returns `undefined` to let the panel
   * fall back to `item.details`.
   */
  onFetchDetails?: (
    item: CatalogItem,
  ) => Promise<CatalogItemDetailsFetchResult | undefined>;
  /**
   * Dropdown options for the Create button. When provided, the button opens a
   * menu instead of calling `onCreateClick` directly.
   */
  createOptions?: DropdownItem[];
  /** Called when the Create button is clicked (used when `createOptions` is absent). */
  onCreateClick?: () => void;
  /** Hides the "Create" button entirely, e.g. when rendering as a read-only picker. Default: false. */
  hideCreateButton?: boolean;
  /**
   * Renders the whole catalog as a read-only browsing surface. Browse cards
   * lose their favorite star, footer divider, and "Featured" tag; the list
   * view loses its "Favorite" column; the "Create" button and the favorites
   * strip are not rendered; and the details panel withholds its favorite star
   * and every mutating action (Share, Publish/Unpublish, Edit, Delete,
   * "Remove from My List", "Revoke access", and the credentials Log in / Log
   * out / manage button). The non-mutating actions — the primary "Use in
   * chat" and Download — still render. Default: false.
   */
  isReadonly?: boolean;
  /** Hides the page heading (title row), e.g. when the host renders its own title outside the catalog. Default: false. */
  hidePageTitle?: boolean;
  /** Initial Browse view mode (`Grid` renders the card grid, `Cards` the list view). Default: `CatalogViewMode.Grid`. */
  initialViewMode?: CatalogViewMode;
  /**
   * Lets the Browse content (card grid and list view) span the full width of
   * its container instead of sitting in a centered, 1180 px-wide column with
   * empty gutters on wide screens. The 32 px side padding is kept either way,
   * and the wider container yields more card columns. Default: false.
   */
  isFullWidth?: boolean;
  /** ID of an item to visually mark as selected (border, tint, and checkmark) in the Browse grid. */
  selectedItemId?: string;
  /**
   * ID of an item whose details panel should open automatically, e.g. when
   * deep-linking from a share invitation. Opens once per distinct id;
   * ignored if no matching item is found in `items`.
   */
  initialDetailsItemId?: string;
  /**
   * When provided, clicking a card in the Browse grid calls this instead of
   * opening the details panel — e.g. to mark it selected in a picker.
   */
  onCardClick?: (item: CatalogItem) => void;
  /** Optional color and typography overrides. */
  styles?: CatalogStyles;
  /** Text overrides forwarded to the item details panel. */
  detailsTexts?: ItemDetailsTexts;
  /**
   * Footer note forwarded to the item details panel's Limits tab, e.g. a
   * link to a full usage-limits page. Omitted (the default) hides the footer.
   */
  detailsLimitsFooterNote?: ReactNode;
  /**
   * Externally-controlled active sort key. When omitted, `Catalog` manages
   * its own sort state internally, defaulting to `CatalogSortKey.RecentlyUpdated`.
   */
  sortKey?: CatalogSortKey;
  /** Called when the user changes the sort option; required to control `sortKey`. */
  onSortChange?: (key: CatalogSortKey) => void;
  /**
   * Externally-controlled set of active "From" topic filter values. When
   * omitted, `Catalog` manages its own filter state internally, defaulting to
   * an empty set (no topics filtered).
   */
  filterTopics?: Set<string>;
  /** Called when the user applies a new topic filter selection; required to control `filterTopics`. */
  onFilterTopicsChange?: (topics: Set<string>) => void;
  /**
   * Externally-controlled "My Apps" filter toggle. When omitted, `Catalog`
   * manages its own state internally, defaulting to `false`.
   */
  isMyAppsActive?: boolean;
  /** Called when the user toggles the "My Apps" filter; required to control `isMyAppsActive`. */
  onMyAppsActiveChange?: (isActive: boolean) => void;
  /**
   * Externally-controlled active entity-type tab id. When omitted, `Catalog`
   * manages its own tab state internally, defaulting to the first tab
   * returned by `buildCatalogTabs`.
   */
  activeTab?: string;
  /** Called when the user switches tabs; required to control `activeTab`. */
  onActiveTabChange?: (tabId: string) => void;
  /**
   * Renders a custom empty state in place of the Browse section's default
   * icon/title (`PanelEmptyState`) when the displayed result set is empty.
   * Called with the live `CatalogEmptyStateContext` only after loading has
   * finished and the result set is empty; not called at all when there are
   * items to show. Returning `null` or `undefined` — or omitting the prop —
   * keeps the existing default empty state, including `titles.noResultsTitle`.
   */
  renderEmptyState?: (context: CatalogEmptyStateContext) => ReactNode;
}

export interface CatalogTitles {
  /** Page heading. Default: 'Catalog'. */
  pageTitle?: string;
  /** Create button label. Default: 'Create'. */
  createLabel?: string;
  /** Favorites section heading. Default: 'Your Favorites'. */
  favoritesTitle?: string;
  /** Browse section heading. Default: 'Browse'. */
  browseTitle?: string;
  /** Search input placeholder. Default: 'Search models, tools, agents…'. */
  searchPlaceholder?: string;
  /**
   * Returns the "no results" heading given the active query.
   * Default: (q) => `No results for "${q}"`.
   */
  noResultsTitle?: (query: string) => string;
  /** The sort control's own name, prepended to its accessible name. Default: 'Sort'. */
  sortLabel?: string;
  /** Label for the "Recently Updated" sort option. Default: 'Recently Updated'. */
  sortRecentlyUpdatedLabel?: string;
  /** Label for the "Newest" sort option. Default: 'Newest'. */
  sortNewestLabel?: string;
  /** Label for the "Name A-Z" sort option. Default: 'Name A-Z'. */
  sortNameAZLabel?: string;
  /** Label for the "Featured" tag on cards. Default: 'Featured'. */
  featuredLabel?: string;
  /** Accessible label for switching to grid view. Default: 'Grid view'. */
  gridViewLabel?: string;
  /** Accessible label for switching to list view. Default: 'List view'. */
  listViewLabel?: string;
  /** Accessible label naming the grid/list view toggle group. Default: 'View mode'. */
  viewToggleLabel?: string;
  /** ARIA label for the page/grid. Default: 'Catalog'. */
  ariaLabel?: string;
  /**
   * Display labels for entity-type filter tabs. Only types present in `items`
   * are shown, and the row is hidden entirely when fewer than two types are
   * present. Defaults: Model → 'Models', Agent → 'Agents',
   * Toolset → 'Toolsets', Skill → 'Skills', Prompt → 'Prompts'.
   */
  tabLabels?: Partial<Record<CatalogEntityType, string>>;
  /** Label for the filter button when nothing is filtered. Default: 'From'. */
  filterFromLabel?: string;
  /** Label for the "My Apps" filter checkbox. Default: 'My'. */
  filterMyAppsLabel?: string;
  /** Label for the Topics section inside the filter dropdown. Default: 'Topics'. */
  filterTopicsLabel?: string;
}

export interface CatalogColors {
  /** Root container background color. Fallback: `--bg-layer-base`. */
  background?: string;
  /** Heading title text color. Fallback: `--text-primary`. */
  headingTitleText?: string;
  /**
   * Featured chip style override, applied to every "Featured" chip in the
   * catalog (both the browse-grid cards and the item details header)
   * regardless of entity type, merged over the chip's default per-entity-type
   * colors, e.g. `{ backgroundColor, color, border }`.
   */
  featuredChipStyle?: CSSProperties;
}

export interface CatalogStyles {
  /** Color customizations applied as CSS custom properties. */
  colors?: CatalogColors;
  /** Typography customizations and class overrides. */
  typography?: CatalogTypography;
}

export interface CatalogTypography {
  /** A single utility class applied to the page heading. Defaults to `'dial-display2-text'`. */
  pageHeadingFontClassName?: string;
  /** Typography class applied to tab text. Defaults to `'dial-body-text'`. */
  tabClassName?: string;
}

export interface EndpointOption {
  /** Display label shown in the endpoint selector, e.g. `'Azure OpenAI Endpoint'`. */
  label: string;
  /** Full base URL for this endpoint. */
  url: string;
  /** Language-keyed code snippets specific to this endpoint. */
  snippets?: CodeSnippet[];
}

export interface ApiResource {
  /** Deployment or model ID used in API calls. */
  modelId?: string;
  /** Full base endpoint URL (used for single-endpoint entities such as Agents). */
  endpointUrl?: string;
}

export interface CatalogContentFileNode {
  /** Discriminates this node as a file. */
  type: CatalogContentNodeType.File;
  /** Opaque id passed back to `onLoadContentFile`. Never parsed by the panel. */
  id: string;
  /** File name shown in the tree row. Not required to be unique across the tree — only `id` must be unique among a node's siblings' descendants. */
  name: string;
}

export interface CatalogContentFolderNode {
  /** Discriminates this node as a folder. */
  type: CatalogContentNodeType.Folder;
  /** Stable key identifying this folder for expand/collapse state. Never parsed by the panel. */
  id: string;
  /** Folder name shown in the tree row. */
  name: string;
  /** Nested folders and files. Empty when the folder carries no children. */
  items: CatalogContentTreeNode[];
}

export type CatalogContentFilePreview =
  | CatalogContentMarkdownPreview
  | CatalogContentTextPreview
  | CatalogContentImagePreview
  | CatalogContentUnsupportedPreview;

export interface CatalogContentMarkdownPreview {
  /** Discriminates this preview as Markdown. */
  type: CatalogContentPreviewType.Markdown;
  /** Markdown source, rendered through the same safe path as the base body. */
  text: string;
}

export interface CatalogContentTextPreview {
  /** Discriminates this preview as text. */
  type: CatalogContentPreviewType.Text;
  /** The file's text content. */
  text: string;
  /** Syntax-highlighting language id (e.g. `'python'`, `'json'`). Omitted renders as unhighlighted monospace text. */
  language?: string;
}

export interface CatalogContentImagePreview {
  /** Discriminates this preview as an image. */
  type: CatalogContentPreviewType.Image;
  /** Already-resolved, browser-loadable image URL. May be a `blob:` URL the host created for this preview. */
  url: string;
}

export interface CatalogContentUnsupportedPreview {
  /** Discriminates this preview as unsupported. */
  type: CatalogContentPreviewType.Unsupported;
}

export interface CatalogItemApiDetails {
  /** Resource identity section (Model ID; single endpoint URL for agents). */
  resource?: ApiResource;
  /** Multi-endpoint selector (Azure OpenAI, Anthropic, Responses, …). When present, the endpoint selector UI replaces the single-endpoint row. */
  endpoints?: EndpointOption[];
  /** Top-level code snippets selectable by language (legacy / non-model entities). */
  snippets?: CodeSnippet[];
  /** Raw cURL request example (Agent / Toolset). */
  requestExample?: string;
  /** Response schema shown as formatted JSON (Agent). */
  responseSchema?: string;
}

export interface CatalogItemDetailsFetchResult extends CatalogItemTabData {
  /** Credential status for the item's own authentication, refreshed alongside tab data. */
  credentials?: CatalogItemCredentials;
}

export interface CatalogItemLimits {
  /** Ordered groups of rows to render, each under its own heading. */
  groups: UsageLimitGroup[];
  /** Worst-case status across all capped rows. Absent when every row is comfortably under the running-low threshold. */
  status?: CatalogLimitStatus;
}

export interface CatalogItemPricing {
  /** Token price rows (input, output, cached, batch). */
  prices?: PricingRow[];
  /** Usage limit rows (daily, weekly, monthly). */
  limits?: UsageLimitRow[];
}

export interface CatalogItemPromptContent {
  /** The item's full text body, already resolved by the host. */
  content: string;
  /** Summary shown above the body. Takes precedence over `CatalogItem.description`, for hosts whose summary is only known once details resolve. */
  description?: string;
  /** Folder/file tree the tab can switch between. A selector is rendered above the body whenever this holds two or more file nodes, at any depth. */
  files?: CatalogContentTreeNode[];
  /** Id of the file `content` was resolved from. The selector opens on it, and reselecting it restores `content` without a reload. */
  selectedFileId?: string;
}

export interface CatalogItemTabData {
  /** Content tab data. When absent the Content tab is hidden. */
  promptContent?: CatalogItemPromptContent;
  /** Overview tab data. When absent the Overview tab is hidden. */
  overview?: CatalogItemOverview;
  /** Pricing tab data. When absent the Pricing tab is hidden. */
  pricing?: CatalogItemPricing;
  /** Usage limits tab data. When absent the Limits tab is hidden. */
  limits?: CatalogItemLimits;
  /** API tab data. When absent the API tab is hidden. */
  api?: CatalogItemApiDetails;
  /** Tools tab data (Toolset only). When absent the Tools tab is hidden. */
  tools?: CatalogItemTools;
}

export interface CatalogItemTools {
  /** Ordered list of tool definitions. */
  tools: ToolDefinition[];
}

export interface CodeSnippet {
  /** Language selector label. */
  language: CodeLanguage;
  /** The code string, preserving whitespace and indentation. */
  code: string;
}

export interface PricingRow {
  /** Row label, e.g. "Input tokens". */
  label: string;
  /** Formatted price string, e.g. "Free" or "$3.00 / 1M". */
  price: string;
}

export interface ToolAnnotation {
  /** Annotation key. */
  key: string;
  /** Annotation value. */
  value: string;
}

export interface ToolDefinition {
  /** Tool name. */
  name: string;
  /** Short description of what the tool does. */
  description?: string;
  /** Input schema parameters. */
  inputParams?: ToolInputParam[];
  /** Tool annotations. */
  annotations?: ToolAnnotation[];
}

export interface ToolInputParam {
  /** Parameter name. */
  name: string;
  /** JSON type, e.g. "string" or "integer". */
  type: string;
  /** Whether the parameter is required. */
  isRequired: boolean;
}

export interface UsageLimitGroup {
  /** Group heading, e.g. "Token limits" or "Cost limits". */
  label: string;
  /** Ordered rows in this group. */
  rows: UsageLimitProgressRow[];
}

export interface UsageLimitProgressRow {
  /** Row label, e.g. "Tokens per day". */
  label: string;
  /** Consumed amount for the limit period. */
  used: number;
  /** Total allowed amount for the limit period. Ignored when `isUnlimited` is true. */
  total: number;
  /** Whether the backend reports this row as effectively unlimited. */
  isUnlimited?: boolean;
  /** Preformatted visible value, e.g. "1,200 / 5,000". Used as-is when `usedLabel`/`totalLabel` are absent. */
  valueLabel?: string;
  /** Preformatted consumed amount, e.g. "$0.00", rendered with the row's normal value weight. Enables rendering `usedLabel` and `totalLabel` with different emphasis instead of the single `valueLabel` string. */
  usedLabel?: string;
  /** Preformatted limit amount, e.g. "$100.00", rendered with heavier emphasis than `usedLabel`. */
  totalLabel?: string;
  /** Accessible value text for the progress bar (`aria-valuetext`), overriding the default `used / total` reading. */
  ariaLabel?: string;
  /** Secondary caption shown under the value for a row with no progress bar (`isUnlimited` or no usable total), e.g. "Follows cost limit". Omitted when absent. */
  noteLabel?: string;
  /** Secondary caption shown under the row's label, e.g. "$20.00 spent". Omitted when absent. */
  captionLabel?: string;
}

export interface UsageLimitRow {
  /** Row label, e.g. "Daily limit". */
  label: string;
  /** Formatted limit value, e.g. "500K tokens / user". */
  value: string;
}

export interface DetailsPanelProps {
  /** The catalog item to display in the panel. */
  item: CatalogItem;
  /** Controls whether the panel is visible. */
  isOpen: boolean;
  /** Initial starred state for the item. Default: `false`. */
  isStarred?: boolean;
  /**
   * When `true`, a fetch for structured detail tabs (Overview/Pricing/API/Tools)
   * is pending; the panel shows a small loading indicator next to the tab row.
   */
  isDetailsLoading?: boolean;
  /** Called when the panel should close (close button or backdrop click). */
  onClose: () => void;
  /**
   * Renders the panel read-only: the favorite star and every action that
   * mutates the item or the caller's relationship to it — Share,
   * Publish/Unpublish, Edit, Delete, "Remove from My List", "Revoke access",
   * and the credentials Log in / Log out / manage button — are withheld. The
   * non-mutating actions (the primary "Use in chat" and Download) still
   * render. Default: false.
   */
  isReadonly?: boolean;
  /** Called when the star/favorite button is toggled. */
  onToggleFavorite?: (id: string, isStarred: boolean) => void;
  /**
   * Additional caller-supplied rule for whether the favorite star is shown in
   * the panel header. Returning `false` hides the star and makes the item
   * non-favoritable from the panel. Defaults to **visible** when omitted.
   */
  isFavoriteVisible?: (item: CatalogItem) => boolean;
  /**
   * Additional caller-supplied rule for whether the "Remove from My List"
   * action is shown, combined (AND) with the built-in
   * `sharedWithMe`/`isMyApp` rule. Defaults to `true` when absent.
   */
  isUnshareVisible?: (item: CatalogItem) => boolean;
  /** Called when the "Use in chat" button is clicked. */
  onUseInChat?: (item: CatalogItem) => void;
  /** Controls whether the primary action button is shown for the item. */
  isPrimaryActionVisible?: (item: CatalogItem) => boolean;
  /** Called when the "Share" button is clicked. */
  onShare?: (item: CatalogItem) => void;
  /** Controls whether the "Publish" action is shown for the item. */
  isPublishVisible?: (item: CatalogItem) => boolean;
  /**
   * Resolves whether whichever of "Publish"/"Unpublish" applies renders as its
   * own button in the details header rather than an entry in its "Manage"
   * menu. Defaults to `false` — the menu entry.
   */
  isPublishPrimary?: (item: CatalogItem) => boolean;
  /** Resolves previously published versions for an item, most recent first. */
  getPublishHistory?: (item: CatalogItem) => Promise<PublishHistoryEntry[]>;
  /** Root-level destination folder nodes offered by the publish flow. */
  publishFolderItems?: PublishFolderNode[];
  /**
   * Externally-controlled set of expanded publish-folder path keys
   * (`path.join('/')`). Pass this together with `onPublishExpandedPathsChange`
   * when the host lazily fetches a folder's children on expand.
   */
  publishExpandedPaths?: Set<string>;
  /** Called when the set of expanded publish folders changes; required to control `publishExpandedPaths`. */
  onPublishExpandedPathsChange?: (paths: Set<string>) => void;
  /** Publish-folder path keys currently being fetched by the host. */
  publishLoadingPaths?: Set<string>;
  /** Resolves whether the current user can publish to a given folder path. */
  hasPublishWriteAccess?: (folderPath: string[]) => boolean;
  /**
   * Initial value for the publish flow's display-author field, and the value
   * it returns to on reset. Resolved by the host from the signed-in user's
   * display name; the catalog library holds no notion of a session.
   */
  publishDefaultAuthor?: string;
  /**
   * Called with the destination folder path, current access rules, trimmed
   * display author, and the credentials opt-in when the user confirms
   * publish/update. The fifth argument is additive — a callback declaring only
   * the first four parameters stays assignable.
   */
  onPublish?: (
    item: CatalogItem,
    folderPath: string[],
    rules: PublicationRule[],
    author: string,
    publishCredentials: boolean,
  ) => Promise<void>;
  /** Called after a successful publish; use this to surface a success notification. */
  onPublishSuccess?: (item: CatalogItem, folderPath: string[]) => void;
  /** Called with the rejection reason when a publish request fails; use this to surface an error notification. */
  onPublishError?: (
    item: CatalogItem,
    folderPath: string[],
    error: unknown,
  ) => void;
  /** Called when the user confirms a new folder name in the publish flow. */
  onCreatePublishFolder?: (parentPath: string[], name: string) => void;
  /** Text overrides forwarded to the publish flow. */
  publishLabels?: PublishPanelLabels & PublishFooterLabels;
  /** Options offered in the access-rules editor's source picker. Defaults to `[]` when absent. */
  ruleSourceOptions?: string[];
  /**
   * Resolves the access rules already configured for a destination folder,
   * called whenever the selected folder changes. The result fully replaces
   * the rules editor's contents. Omit to skip pre-filling entirely.
   */
  onFetchExistingRules?: (folderPath: string[]) => Promise<PublicationRule[]>;
  /**
   * Renders the Share popover content, anchored to whichever surface carries
   * Share — the header button, or the Manage trigger when `isSharePrimary`
   * has moved the entry into that menu. When provided, choosing Share opens
   * this popover instead of calling `onShare`.
   */
  shareOverlay?: (item: CatalogItem, onClose: () => void) => ReactNode;
  /**
   * Additional caller-supplied rule for whether the "Share" action is shown
   * for the item, combined (AND) with the built-in ownership/type rule.
   * Absent means the built-in rule alone decides.
   */
  isShareVisible?: (item: CatalogItem) => boolean;
  /**
   * Resolves whether "Share" renders as its own button in the details header
   * rather than an entry in its "Manage" menu. Defaults to `true` — the
   * button. Returning `false` moves it into the menu, beside "Delete".
   */
  isSharePrimary?: (item: CatalogItem) => boolean;
  /** Called when the "Edit" button is clicked. Shown only when the item's `isEditable` is `true`. */
  onEdit?: (item: CatalogItem) => void;
  /**
   * Called when the "Download" action is clicked, with no confirmation step.
   * When "Download" renders in the Manage menu (see `isDownloadPrimary`), the
   * panel does not await the result or show a pending state, so the host
   * owns any progress and failure feedback. When "Download" is the primary
   * action, the panel awaits this call and shows a pending/disabled state
   * for its duration; the host still owns failure feedback either way.
   */
  onDownload?: (item: CatalogItem) => Promise<void> | void;
  /**
   * Narrows which items offer the "Download" action. Defaults to `true`
   * (visible for every item) whenever `onDownload` is supplied.
   */
  isDownloadVisible?: (item: CatalogItem) => boolean;
  /**
   * Resolves whether an item's Download action renders as the primary action
   * (in the same slot as "Use in chat") instead of a Manage-menu entry.
   * Defaults to `item.type === CatalogEntityType.Skill`. An item whose
   * Download is primary never also shows it in the Manage menu.
   */
  isDownloadPrimary?: (item: CatalogItem) => boolean;
  /**
   * Resolves the text of a file picked in the Content tab, given its opaque
   * `id`. The panel shows a loading state while it is pending and renders the
   * resolved text as the body; resolving `undefined` or rejecting leaves the
   * body showing `texts.contentFileErrorLabel`. Superseded by
   * `onLoadContentFilePreview` for a given pick when both are supplied.
   */
  onLoadContentFile?: (fileId: string) => Promise<string | undefined>;
  /**
   * Resolves a picked file's typed preview, given its opaque `id`. Takes
   * precedence over `onLoadContentFile` when both are supplied. Resolving
   * `undefined` or rejecting leaves the body showing
   * `texts.contentFileErrorLabel`.
   */
  onLoadContentFilePreview?: (
    fileId: string,
  ) => Promise<CatalogContentFilePreview | undefined>;
  /**
   * Renders a picked file through a host-owned preview surface. Takes
   * precedence over both loading callbacks. The file id is opaque to the
   * panel; `fileName` is the basename resolved from the supplied tree.
   */
  renderContentFilePreview?: (fileId: string, fileName: string) => ReactNode;
  /**
   * Called immediately when the "Delete" button is clicked, with no
   * confirmation step. Shown only when the item's `isMyApp` is `true` and
   * its `type` is `Application` or `Toolset`. May return a promise; the
   * button shows a disabled state while pending.
   */
  onDelete?: (item: CatalogItem) => Promise<void> | void;
  /**
   * Called when removal is confirmed via the confirmation popup, for an item
   * shared with the current user (`sharedWithMe: true`). May return a
   * promise; the popup shows a loading state and prevents duplicate
   * submission while pending.
   */
  onUnshare?: (item: CatalogItem) => Promise<void> | void;
  /**
   * Called when revocation is confirmed for an item the current user owns
   * (`isMyApp: true`), removing every recipient's shared access at once. May
   * return a promise; the confirmation shows a loading state and prevents
   * duplicate submission while pending. The item stays in the owner's
   * catalog, so the panel returns to its details content on success.
   */
  onRevokeShare?: (item: CatalogItem) => Promise<void> | void;
  /**
   * Resolves how many users currently hold shared access to an owned item.
   * Called when the owner opens the Manage menu, so "Revoke access" is gated
   * and labelled on a count that is never stale. `0` hides the action;
   * `undefined` (or a rejection) leaves it reachable without a count. Omit to
   * offer the action for every owned item.
   */
  onFetchRecipientsCount?: (item: CatalogItem) => Promise<number | undefined>;
  /**
   * Additional caller-supplied rule for whether "Revoke access" is shown,
   * combined (AND) with the built-in `isMyApp` rule and the recipient count.
   * Defaults to `true` when absent.
   */
  isRevokeShareVisible?: (item: CatalogItem) => boolean;
  /**
   * Called when unpublish is confirmed, with the published folder's path
   * segments — the same `string[]` shape `onPublish` receives. May return a
   * promise; the confirmation shows a loading state and prevents duplicate
   * submission while pending. The published copy survives until an
   * administrator approves the request, so the panel stays open, the item
   * stays visible, and cached publish history is left untouched on success.
   */
  onUnpublish?: (
    item: CatalogItem,
    folderPath: string[],
  ) => Promise<void> | void;
  /**
   * Additional caller-supplied rule for whether "Unpublish" is shown,
   * combined (AND) with the presence of `onUnpublish` and at least one
   * resolved publish-history entry. Defaults to `true` when absent.
   */
  isUnpublishVisible?: (item: CatalogItem) => boolean;
  /**
   * Called when the credentials login form is submitted. `level` identifies
   * which credentials slot the call applies to (`USER` for the current
   * user's own credentials; `GLOBAL` for organization-wide credentials,
   * only reachable by an admin managing a public item). `apiKey` is present
   * for API-key authentication and absent for OAuth (where this call should
   * initiate a redirect). Shown only when the item's `credentials` field is
   * present with an `authenticationType` other than `NONE`. May return a
   * promise; the panel awaits it before refreshing credential status via
   * `onFetchDetails`.
   */
  onLogin?: (
    item: CatalogItem,
    params: { level: CredentialsLevel; apiKey?: string },
  ) => Promise<void> | void;
  /**
   * Called when logout is confirmed in the credentials section, for the
   * given credentials `level`. May return a promise; the panel awaits it
   * before refreshing credential status via `onFetchDetails`.
   */
  onLogout?: (
    item: CatalogItem,
    params: { level: CredentialsLevel },
  ) => Promise<void> | void;
  /** Text overrides for all user-visible strings. */
  texts?: ItemDetailsTexts;
  /** Grouped style overrides. */
  styles?: ItemDetailsStyles;
  /**
   * Footer note rendered below the Limits tab's rows, e.g. a link to a
   * full usage-limits page. Omitted (the default) hides the footer entirely.
   */
  limitsFooterNote?: ReactNode;
}

