FavoriteCard: FC<FavoriteCardProps> = ({
  item,
  initialIsStarred = true,
  onToggle,
  isFavoriteVisible,
  onClick,
  nameClassName,
  colors,
  versionClassName,
  lastUsedClassName,
  query,
  addToFavoritesAriaLabel = 'Add to favorites',
  removeFromFavoritesAriaLabel = 'Remove from favorites',
  isSelected = false,
  credentialsBadgeLoggedOutLabel,
}) => {
  const [isStarred, setIsStarred] = useState(initialIsStarred);
  const [isLeaving, setIsLeaving] = useState(false);

  const handleToggle = (e: MouseEvent<HTMLElement>) => {
    e.stopPropagation();
    const next = !isStarred;
    setIsStarred(next);
    if (!next) {
      setIsLeaving(true);
    } else {
      onToggle?.(item.id, next);
    }
  };

  const handleClick = onClick && !isLeaving ? () => onClick(item) : undefined;

  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLElement>) => {
      if (!onClick || isLeaving) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onClick(item);
      }
    },
    [onClick, item, isLeaving],
  );

  return (
    <CardShell
      data-card-id={item.id}
      role={handleClick != null ? 'button' : undefined}
      tabIndex={handleClick != null ? 0 : undefined}
      aria-label={item.name}
      className={mergeClasses(
        'box-border min-w-0 cursor-pointer flex-row items-start gap-1 text-start',
        isLeaving && styles.cardLeaving,
        isSelected && styles.selectedCard,
        CATALOG_CLASS.favoriteCard,
      )}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      onAnimationEnd={
        isLeaving
          ? (e) => {
              if (e.currentTarget === e.target) onToggle?.(item.id, false);
            }
          : undefined
      }
    >
      {isSelected && (
        <IconCheck
          size={DIAL_ICON_SIZE.SM}
          className={mergeClasses(
            'absolute end-3 top-3 shrink-0',
            styles.selectedCheck,
          )}
          aria-hidden
          stroke={DIAL_KIT_ICON_STROKE}
        />
      )}

      <div className="flex min-w-0 flex-1 flex-col items-start gap-1">
        <AppIdentity
          icon={item.iconUrl}
          type={item.type}
          name={item.name}
          version={item.version}
          lastUsed={item.lastUsed}
          size={DeploymentSize.LG}
          query={query}
          className="min-w-0 self-stretch"
          styles={{
            colors,
            typography: {
              nameClassName,
              versionClassName,
              lastUsedClassName,
            },
          }}
          iconOverlay={
            <CredentialsBadge
              credentials={item.credentials}
              loggedOutLabel={credentialsBadgeLoggedOutLabel}
            />
          }
        />
      </div>
      {isFavoriteVisible?.(item) !== false && (
        <StarToggleButton
          isStarred={isStarred}
          size={ElementSize.Small}
          onClick={handleToggle}
          ariaLabel={
            isStarred ? removeFromFavoritesAriaLabel : addToFavoritesAriaLabel
          }
          className="self-end"
        />
      )}
    </CardShell>
  );
}

export interface FavoriteCardProps {
  /** The favorite item to display. */
  item: CatalogItem;
  /** Initial starred state. Default: true — items in favorites are starred by default. */
  initialIsStarred?: boolean;
  /** Called when the star button is toggled. */
  onToggle?: (id: string, isStarred: boolean) => void;
  /** Rule for whether the favorite star is shown; `false` hides the star and makes the item non-favoritable. Defaults to visible when omitted. */
  isFavoriteVisible?: (item: CatalogItem) => boolean;
  /** Called when the card body is clicked. */
  onClick?: (item: CatalogItem) => void;
  /** Typography CSS class for the entity name. Default: 'dial-body-semi-text'. */
  nameClassName?: string;
  /** Color overrides applied as CSS custom properties. */
  colors?: AppIdentityColors;
  /** Typography CSS class for the version string. Default: `'dial-tiny-text'`. */
  versionClassName?: string;
  /** Typography CSS class for the last-used text. Default: `'dial-tiny-text'`. */
  lastUsedClassName?: string;
  /** Search query string; matching text in the name is highlighted when provided. */
  query?: string;
  /** Accessible label for the star button when the item is not starred. Default: `'Add to favorites'`. */
  addToFavoritesAriaLabel?: string;
  /** Accessible label for the star button when the item is already starred. Default: `'Remove from favorites'`. */
  removeFromFavoritesAriaLabel?: string;
  /** Whether this card represents the currently selected item — shows an accent border, tinted background, and a checkmark. Default: false. */
  isSelected?: boolean;
  /** Accessible label for the logged-out warning icon on the entity avatar, and the text shown in its hover tooltip. Default: `'Authorize to use this toolset.'`. */
  credentialsBadgeLoggedOutLabel?: string;
}

Filter: FC<FilterProps> = ({
  checked,
  onChange,
  values,
  isMyAppsActive,
  onMyAppsChange,
  myAppsLabel = 'My',
  topicsLabel = 'Topics',
  defaultLabel = 'From',
  clearLabel = 'Clear',
  applyLabel = 'Apply',
  typography,
  colors,
}) => {
  const isActive = (isMyAppsActive ?? false) || checked.size > 0;
  const [isOpen, setIsOpen] = useState(false);

  /* Applied to the trigger and the overlay separately — the dropdown portals
   * its overlay, so it is not a DOM descendant of the trigger. */
  const cssVars = buildCssVars({
    '--cat-filter-btn-bg': colors?.buttonBackground,
    '--cat-filter-btn-border': colors?.buttonBorder,
    '--cat-filter-btn-border-hover': colors?.buttonBorderHover,
    '--cat-filter-btn-border-focus': colors?.buttonBorderFocus,
    '--cat-filter-btn-border-active': colors?.buttonBorderActive,
    '--cat-filter-btn-border-open': colors?.buttonBorderOpen,
    '--cat-filter-btn-label': colors?.buttonLabel,
    '--cat-filter-btn-funnel': colors?.buttonFunnel,
    '--cat-filter-btn-chevron': colors?.buttonChevron,
    '--cat-filter-overlay-bg': colors?.overlayBackground,
    '--cat-filter-overlay-border': colors?.overlayBorder,
    '--cat-filter-row-label': colors?.rowLabel,
    '--cat-filter-section-label': colors?.sectionLabel,
    '--cat-filter-divider': colors?.divider,
    '--cat-filter-footer-border': colors?.footerBorder,
  });

  const topics = useMemo(
    () => (values != null ? [...values].sort() : []),
    [values],
  );

  const buttonLabel = getFilterButtonLabel(
    checked,
    values,
    isMyAppsActive,
    myAppsLabel,
    defaultLabel,
  );

  // Pending (buffered) state — committed to parent only on Apply.
  const [pendingChecked, setPendingChecked] = useState<Set<string>>(
    () => new Set(checked),
  );
  const [pendingMyApps, setPendingMyApps] = useState(isMyAppsActive ?? false);

  // Sync pending from applied state each time the dropdown opens.
  useEffect(() => {
    if (!isOpen) return;
    setPendingChecked(new Set(checked));
    setPendingMyApps(isMyAppsActive ?? false);
  }, [isOpen, checked, isMyAppsActive]);

  /*
   * Keyboard navigation — roving tabindex across checkbox rows only.
   * Footer buttons live outside the roving group (natural tab order).
   */
  const totalItems = topics.length + 1;
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const rowRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const triggerRef = useRef<HTMLButtonElement>(null);

  const focusRow = useCallback(
    (index: number) => {
      const clamped = (index + totalItems) % totalItems;
      setFocusedIndex(clamped);
      rowRefs.current[clamped]?.focus();
    },
    [totalItems],
  );

  // Focus first row after overlay renders.
  useEffect(() => {
    if (!isOpen) {
      setFocusedIndex(-1);
      return;
    }
    const frame = requestAnimationFrame(() => focusRow(0));
    return () => cancelAnimationFrame(frame);
  }, [isOpen, focusRow]);

  const handleOpenChange = (next: boolean) => {
    setIsOpen(next);
    if (!next) triggerRef.current?.focus();
  };

  const handleTriggerKeyDown = (e: KeyboardEvent<HTMLButtonElement>) => {
    if (e.key === 'ArrowDown' && !isOpen) {
      e.preventDefault();
      setIsOpen(true);
    }
  };

  /*
   * Arrow keys navigate checkbox rows; Escape closes. Footer buttons stop
   * propagation of Arrow keys so they don't accidentally move row focus.
   */
  const handleMenuKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      focusRow(focusedIndex + 1);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      focusRow(focusedIndex - 1);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      setIsOpen(false);
      triggerRef.current?.focus();
    }
  };

  const handleApply = () => {
    onChange(pendingChecked);
    onMyAppsChange?.(pendingMyApps);
    handleOpenChange(false);
  };

  const handleClear = () => {
    onChange(new Set());
    onMyAppsChange?.(false);
    handleOpenChange(false);
  };

  return (
    <Dropdown
      matchReferenceWidth={false}
      placement="bottom-start"
      open={isOpen}
      onOpenChange={handleOpenChange}
      listClassName="!bg-transparent !shadow-none !p-0"
      renderOverlay={() => (
        <div
          role="menu"
          aria-label={defaultLabel}
          tabIndex={-1}
          /*
           * Bound to the kit Dropdown's own live available-height var (set by
           * floating-ui) so the topics list, not the floating panel, absorbs
           * any height constraint. Without it both scroll: the panel keeps its
           * default overflow and the list keeps its full 344px, so a viewport
           * too short for the two of them plus the header and footer leaves
           * the user with two scrollbars. The -8px accounts for this overlay's
           * own p-[6px] plus the panel's border.
           */
          style={{
            ...cssVars,
            maxHeight: 'calc(var(--fui-available-height, 9999px) - 8px)',
          }}
          className={mergeClasses(
            'flex min-w-[360px] flex-col rounded-xl p-[6px]',
            styles.overlay,
          )}
          onKeyDown={handleMenuKeyDown}
        >
          {/* My Apps row — the kit's own multiselect menu row, so its rest,
              hover, focus and checked states come from the Menu-item spec. */}
          <MenuItem
            role="menuitemcheckbox"
            aria-checked={pendingMyApps}
            mark={MenuItemMark.Checkbox}
            selected={pendingMyApps}
            label={myAppsLabel}
            labelClassName={mergeClasses(
              styles.rowLabel,
              typography?.filterButtonClassName ?? 'dial-small-semi-text',
            )}
            /* Its height is a `height`, so as a flex child of the panel it
               would shrink instead of leaving the topics list to scroll. */
            className="shrink-0"
            tabIndex={focusedIndex === 0 ? 0 : -1}
            ref={(el) => {
              rowRefs.current[0] = el;
            }}
            onClick={() => setPendingMyApps(!pendingMyApps)}
          />

          {topics.length > 0 && (
            <>
              <div
                role="separator"
                className={mergeClasses('my-1 h-px', styles.divider)}
                aria-hidden
              />
              <div
                className={mergeClasses(
                  'px-[10px] pb-1 pt-[10px]',
                  typography?.filterSectionLabelClassName ??
                    'dial-tiny-lead-semi-text',
                  styles.sectionLabel,
                )}
                aria-hidden
              >
                {topicsLabel}
              </div>
              {/* The options are their own scroll box at the design's maximum
                  list length, so the My Apps row, the section heading and the
                  Clear/Apply footer stay put as the topics scroll. `min-h-0`
                  lets it give way when the panel's available height is under
                  that maximum, keeping it the only thing that scrolls. */}
              <div
                className={mergeClasses(
                  SELECT_LIST_MAX_HEIGHT_CLASS_NAME,
                  'flex min-h-0 flex-col gap-1 overflow-y-auto',
                )}
              >
                {topics.map((topic, i) => {
                  const isChecked = pendingChecked.has(topic);
                  const idx = i + 1;
                  const toggle = () =>
                    setPendingChecked(toggleTopic(topic, pendingChecked));
                  return (
                    <MenuItem
                      key={topic}
                      role="menuitemcheckbox"
                      aria-checked={isChecked}
                      mark={MenuItemMark.Checkbox}
                      selected={isChecked}
                      label={topic}
                      labelClassName={styles.rowLabel}
                      className="shrink-0"
                      tabIndex={focusedIndex === idx ? 0 : -1}
                      ref={(el) => {
                        rowRefs.current[idx] = el;
                      }}
                      onClick={toggle}
                    />
                  );
                })}
              </div>
            </>
          )}

          <div
            className={mergeClasses(
              'mt-1 flex shrink-0 items-center px-1 py-3',
              styles.footer,
            )}
            onKeyDown={(e) => {
              if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
                e.stopPropagation();
              }
            }}
          >
            <GhostButton label={clearLabel} onClick={handleClear} />

            <PrimaryButton
              label={applyLabel}
              className="ms-auto"
              onClick={handleApply}
            />
          </div>
        </div>
      )}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="menu"
        aria-expanded={isOpen}
        onKeyDown={handleTriggerKeyDown}
        style={cssVars}
        className={mergeClasses(
          'flex h-12 shrink-0 cursor-pointer items-center gap-[7px] whitespace-nowrap rounded-lg px-[18px]',
          styles.filterBtn,
          isActive && styles.filterBtnActive,
          isOpen && styles.filterBtnOpen,
        )}
      >
        <IconFilter
          size={DIAL_ICON_SIZE.SM}
          stroke={DIAL_KIT_ICON_STROKE}
          className={mergeClasses('shrink-0', styles.filterBtnFunnel)}
          aria-hidden
        />
        <span
          className={mergeClasses(
            styles.filterBtnLabel,
            typography?.filterButtonClassName ?? 'dial-small-semi-text',
          )}
        >
          {buttonLabel}
        </span>
        <IconChevronDown
          size={14}
          stroke={DIAL_KIT_ICON_STROKE}
          className={mergeClasses(
            'shrink-0 transition-transform duration-150',
            styles.filterBtnChevron,
            isOpen && 'rotate-180',
          )}
          aria-hidden
        />
      </button>
    </Dropdown>
  );
}

