export interface CatalogItemCredentials {
  /** Authentication mechanism required by the item. */
  authenticationType: ToolsetAuthenticationType;
  /** Sign-in status of the current user's personal (`USER`-level) credentials. */
  userStatus?: CredentialStatus;
  /** Sign-in status of the organization-wide (`GLOBAL`-level) credentials. */
  globalStatus?: CredentialStatus;
  /** Whether the item is shared publicly (affects badge/action wording). Resolved by the app. */
  isPublic?: boolean;
  /** Whether the current user may manage both `USER` and `GLOBAL` credentials (admin on a public item). Resolved by the app. */
  isManageableByAdmin?: boolean;
  /** Name of the API key header, shown as a hint in the login form. Only set for `API_KEY` authentication. */
  apiKeyHeader?: string;
  /** Already-formatted relative time (e.g. `'3 weeks ago'`) since the personal API key was added. Only set for `API_KEY` authentication when `userStatus` is `SIGNED_IN`. Omit to hide the "Added …" caption. */
  userApiKeyAddedWhen?: string;
  /** Already-formatted relative time since the organization-wide API key was added. Only set for `API_KEY` authentication when `globalStatus` is `SIGNED_IN`. Omit to hide the "Added …" caption. */
  globalApiKeyAddedWhen?: string;
}

filterCatalogItems = (
  items: CatalogItem[],
  query: string,
): CatalogItem[] => {
  const queryLower = query.trim().toLowerCase();

  if (!queryLower) return items;

  return items.filter((item) => item.name.toLowerCase().includes(queryLower));
}

sortCatalogItems = (
  items: CatalogItem[],
  sortKey: string,
): CatalogItem[] => {
  const featured = items.filter((i) => i.isFeatured);
  const rest = items.filter((i) => !i.isFeatured);

  const sortGroup = (group: CatalogItem[]): CatalogItem[] => {
    if (sortKey === CatalogSortKey.NameAZ) {
      return [...group].sort((a, b) =>
        a.name.trim().toLowerCase().localeCompare(b.name.trim().toLowerCase()),
      );
    }
    if (sortKey === CatalogSortKey.RecentlyUpdated) {
      return [...group].sort((a, b) => {
        if (!a.updatedAt && !b.updatedAt) return 0;
        if (!a.updatedAt) return 1;
        if (!b.updatedAt) return -1;
        return b.updatedAt - a.updatedAt;
      });
    }
    if (sortKey === CatalogSortKey.Newest) {
      return [...group].sort((a, b) => {
        if (!a.createdAt && !b.createdAt) return 0;
        if (!a.createdAt) return 1;
        if (!b.createdAt) return -1;
        return b.createdAt - a.createdAt;
      });
    }
    return group;
  };

  return [...sortGroup(featured), ...sortGroup(rest)];
}

buildCatalogTabs = (
  items: CatalogItem[],
  tabLabels?: Partial<Record<CatalogEntityType, string>>,
): TabModel[] => {
  const labels = { ...DEFAULT_TAB_LABELS, ...tabLabels };
  const presentTypes = new Set(items.map((item) => item.type));
  return TAB_ORDER.filter((type) => presentTypes.has(type)).map((type) => ({
    id: type,
    label: labels[type] ?? type,
  }));
}

getCredentialsBadgeState = (
  credentials: CatalogItemCredentials,
): CredentialsBadgeState | undefined => {
  if (credentials.authenticationType === ToolsetAuthenticationType.None) {
    return undefined;
  }

  const isUserSignedIn = isSignedIn(credentials.userStatus);
  const isGlobalSignedIn = isSignedIn(credentials.globalStatus);

  return !isUserSignedIn && !isGlobalSignedIn
    ? CredentialsBadgeState.LoggedOut
    : undefined;
}

getCredentialsUiState = (
  credentials: CatalogItemCredentials,
): CredentialsUiState => {
  const isUserSignedIn = isSignedIn(credentials.userStatus);
  const isGlobalSignedIn = isSignedIn(credentials.globalStatus);

  if (credentials.isManageableByAdmin) {
    return CredentialsUiState.ManageCredentials;
  }
  if (credentials.isPublic && !isUserSignedIn) {
    return CredentialsUiState.LoginWithMyCreds;
  }
  if (!isUserSignedIn && !isGlobalSignedIn) {
    return CredentialsUiState.LogIn;
  }
  return CredentialsUiState.LogOut;
}

