}) => {
  const cssVars = {
    '--cat-browse-divider': browseStyles?.colors?.divider,
  } as CSSProperties;

  return (
    <section
      className={mergeClasses(
        'flex-shrink-0 px-4',
        styles.section,
        CATALOG_CLASS.toolbar,
      )}
      style={cssVars}
    >
      <TitleRow
        styles={browseStyles}
        query={query}
        onQueryChange={onQueryChange}
        searchPlaceholder={searchPlaceholder}
        gridViewLabel={gridViewLabel}
        listViewLabel={listViewLabel}
        viewToggleLabel={viewToggleLabel}
        sortKey={sortKey}
        sortOptions={sortOptions}
        onSortChange={onSortChange}
        sortLabel={sortLabel}
        filters={filters}
        onFiltersChange={onFiltersChange}
        filterValues={filterValues}
        isMyAppsActive={isMyAppsActive}
        onMyAppsChange={onMyAppsChange}
