        filterMyAppsLabel={filterMyAppsLabel}
        filterTopicsLabel={filterTopicsLabel}
        {...innerProps}
      />
    </section>
  );
}

Card: FC<CardProps> = ({
  item,
  query = '',
  onClick,
  initialIsStarred = false,
  onToggle,
  isFavoriteVisible,
  featuredLabel = 'Featured',
  addToFavoritesAriaLabel = 'Add to favorites',
  removeFromFavoritesAriaLabel = 'Remove from favorites',
  isSelected = false,
  className,
  styles: cardStyles,
  credentialsBadgeLoggedOutLabel,
  isReadonly = false,
}) => {
  const [isStarred, setIsStarred] = useState(initialIsStarred);

  /*
   * Resyncs local optimistic state when the caller's `favoriteIds` reverts
   * after a failed toggle request — without this, the star stays stuck on
   * whatever the user last clicked (issue #7924).
   */
  useEffect(() => {
    setIsStarred(initialIsStarred);
  }, [item.id, initialIsStarred]);

  const descriptionClassName =
    cardStyles?.typography?.descriptionClassName ?? 'dial-small-paragraph-text';

  const featuredChipClassName = cardStyles?.typography?.featuredChipClassName;
  const folderLabelClassName =
    cardStyles?.typography?.folderLabelClassName ?? 'dial-tiny-text';
  const folderLeafClassName =
    cardStyles?.typography?.folderLeafClassName ?? 'dial-tiny-semi-text';

  const cssVars = buildCssVars({
    '--cg-description-text': cardStyles?.colors?.textSecondary,
    '--cg-selected-border': cardStyles?.colors?.selectedBorder,
    '--cg-selected-bg': cardStyles?.colors?.selectedBackground,
    '--cg-check-icon': cardStyles?.colors?.checkIcon,
    '--cg-footer-border': cardStyles?.colors?.footerBorder,
  });

  const isFeaturedVisible = !isReadonly && item.isFeatured === true;
  const isStarVisible = !isReadonly && isFavoriteVisible?.(item) !== false;
  /* Read-only cards drop the whole footer row once the folder path — the only
   * thing left in it without the star — has nothing to render. */
  const isFooterVisible = !isReadonly || item.folder.length > 0;

  const handleClick = onClick
    ? (e: MouseEvent<HTMLElement>) => {
        if (!isLinkEvent(e)) onClick(item);
      }
    : undefined;

  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLElement>) => {
      if (!onClick || isLinkEvent(e)) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onClick(item);
      }
    },
    [onClick, item],
  );

  const handleStarToggle = useCallback(
    (e: MouseEvent<HTMLElement>) => {
      e.stopPropagation();
      const next = !isStarred;
      setIsStarred(next);
      onToggle?.(item.id, next);
    },
    [isStarred, onToggle, item.id],
  );

  return (
    <CardShell
      {...(onClick
        ? {
            role: 'button' as const,
            tabIndex: 0,
            onClick: handleClick,
            onKeyDown: handleKeyDown,
          }
        : {})}
      aria-label={item.name}
      style={cssVars}
      className={mergeClasses(
        'box-border cursor-pointer gap-3',
        styles.card,
        isFeaturedVisible ? styles.featuredCard : undefined,
        isSelected ? styles.selectedCard : undefined,
        className,
        CATALOG_CLASS.card,
      )}
    >
      {isFeaturedVisible && (
        <div className="absolute end-[22px] top-0 -translate-y-1/2">
          <FeaturedChip
            label={featuredLabel}
            type={item.type}
            className={featuredChipClassName}
            style={cardStyles?.colors?.featuredChipStyle}
          />
        </div>
      )}

      {isSelected && (
        <IconCheck
          size={DIAL_ICON_SIZE.SM}
          className={mergeClasses(
            'absolute end-3 top-3 shrink-0',
            styles.checkIcon,
          )}
          aria-hidden
          stroke={DIAL_KIT_ICON_STROKE}
        />
      )}

      <AppIdentity
        icon={item.iconUrl}
        type={item.type}
        name={item.name}
        version={item.version}
        size={DeploymentSize.SM}
        query={query}
        iconClassName={styles.cardIcon}
        iconOverlay={
          <CredentialsBadge
            credentials={item.credentials}
            loggedOutLabel={credentialsBadgeLoggedOutLabel}
          />
        }
      />

      <div
        className={mergeClasses(
          /*
           * `min-h` is two line-heights, not a fixed px value: `line-clamp-2`
           * limits the text to 2 lines but `overflow: hidden` clips at the box
           * height, so any box taller than 2 lines paints the clamped-away
           * lines. `2lh` tracks whichever typography class is applied.
           */
          'line-clamp-2 min-h-[2lh] break-words',
          styles.description,
        )}
      >
        {item.description && (
          <MarkdownRenderer
            content={item.description}
            classNames={
              {
                p: descriptionClassName,
                ul: descriptionClassName,
                ol: descriptionClassName,
                h1: descriptionClassName,
                h2: descriptionClassName,
                h3: descriptionClassName,
                h4: descriptionClassName,
                h5: descriptionClassName,
                h6: descriptionClassName,
              } satisfies MarkdownRendererClassNames
            }
            components={DESCRIPTION_MARKDOWN_COMPONENTS}
          />
        )}
      </div>

      {/* `mt-auto` pins the topics row and footer to the card bottom — the job
       * `flex-1` on the description used to do before it broke the clamp. */}
      <div className="mt-auto flex items-center gap-2">
        <TopicsLine topics={item.topics} />
      </div>

      {isFooterVisible && (
        <div
          className={mergeClasses(
            'pt-3',
            !isReadonly && mergeClasses('border-t', styles.footer),
          )}
        >
          <div className="flex items-center gap-2">
            <div className="min-w-0 flex-1">
              {item.folder.length > 0 && (
                <FolderPath
                  segments={item.folder}
                  labelClassName={folderLabelClassName}
                  leafClassName={folderLeafClassName}
                />
              )}
            </div>
            {isStarVisible && (
              <StarToggleButton
                isStarred={isStarred}
                size={ElementSize.Small}
                onClick={handleStarToggle}
                ariaLabel={
                  isStarred
                    ? removeFromFavoritesAriaLabel
                    : addToFavoritesAriaLabel
                }
                className={mergeClasses(
                  styles.starBtn,
                  !isStarred && styles.emptyStarHidden,
                )}
              />
            )}
          </div>
        </div>
      )}
    </CardShell>
  );
}

CardGrid: FC<CardGridProps> = memo(
  ({
    items,
    query = '',
    onToggleFavorite,
    isFavoriteVisible,
    onItemClick,
    titles,
    isLoading,
    selectedItemId,
    skeletonColor = styles.skeletonColor,
    skeletonCardBackground,
    isReadonly = false,
    isFullWidth = false,
    featuredChipStyle,
  }) => {
    const noResultsTitle = titles?.noResultsTitle ?? 'No results';
    const featuredLabel = titles?.featuredLabel ?? 'Featured';
    const addToFavoritesAriaLabel =
      titles?.addToFavoritesAriaLabel ?? 'Add to favorites';
    const removeFromFavoritesAriaLabel =
      titles?.removeFromFavoritesAriaLabel ?? 'Remove from favorites';
    const credentialsBadgeLoggedOutLabel =
      titles?.credentialsBadgeLoggedOutLabel ??
      'Authorize to use this toolset.';

    const { containerRef, startRow, endRow, columnCount, totalHeight } =
      useScrollVirtualizer(items.length, { isFullWidth });

    const rowData = useMemo<CardRowData>(
      () => ({
        items,
        columnCount,
        query,
        onToggleFavorite,
        isFavoriteVisible,
        onItemClick,
        featuredLabel,
        addToFavoritesAriaLabel,
        removeFromFavoritesAriaLabel,
        selectedItemId,
        credentialsBadgeLoggedOutLabel,
        isReadonly,
        featuredChipStyle,
      }),
      [
        items,
        columnCount,
        query,
        onToggleFavorite,
        isFavoriteVisible,
        onItemClick,
        featuredLabel,
        addToFavoritesAriaLabel,
        removeFromFavoritesAriaLabel,
        selectedItemId,
        credentialsBadgeLoggedOutLabel,
        isReadonly,
        featuredChipStyle,
      ],
    );

    if (isLoading) {
      return (
        <div
          className="grid gap-5 p-5"
          style={{
            gridTemplateColumns: `repeat(${columnCount}, minmax(0, 1fr))`,
            ...buildCssVars({
              '--cg-skeleton-card-bg': skeletonCardBackground,
            }),
          }}
        >
          {Array.from({ length: columnCount * SKELETON_ROW_COUNT }, (_, i) => (
            <div
              key={i}
              className={mergeClasses(
                'rounded-md border p-4',
                styles.skeletonCard,
              )}
              style={{ height: CARD_HEIGHT }}
            >
              <Skeleton
                avatar={{ size: 48, shape: SkeletonAvatarShape.Square }}
                showTitle={{ width: `${60 + ((i * 17) % 30)}%` }}
                paragraph={{ rows: 3 }}
                active
                color={skeletonColor}
              />
            </div>
          ))}
        </div>
      );
    }

    if (items.length === 0) {
      return (
        <div className="flex size-full flex-col items-center justify-center">
          <PanelEmptyState label={noResultsTitle} />
        </div>
      );
    }

    return (
      <div
        ref={containerRef}
        className="relative"
        style={{ height: totalHeight }}
      >
        {Array.from({ length: endRow - startRow }, (_, i) => {
          const rowIndex = startRow + i;
          return (
            <CardRowRenderer key={rowIndex} rowIndex={rowIndex} {...rowData} />
          );
        })}
      </div>
    );
  },
)

CardRowRenderer: FC<CardRowRendererProps> = memo(
  ({
    rowIndex,
    items,
    columnCount,
    query,
    onToggleFavorite,
    isFavoriteVisible,
    onItemClick,
    featuredLabel,
    addToFavoritesAriaLabel,
    removeFromFavoritesAriaLabel,
    selectedItemId,
    credentialsBadgeLoggedOutLabel,
    isReadonly,
    featuredChipStyle,
  }) => {
    const start = rowIndex * columnCount;
    const rowItems = items.slice(start, start + columnCount);

    const style: CSSProperties = {
      top: rowIndex * CARD_ROW_HEIGHT,
      height: CARD_ROW_HEIGHT,
    };

    return (
      <div style={style} className="absolute flex w-full gap-5 pb-5">
        {Array.from({ length: columnCount }, (_, colIndex) => {
          const item = rowItems[colIndex];
          return (
            <div
              key={item?.id ?? `spacer-${colIndex}`}
              className="h-full min-w-0 flex-1"
            >
              {item && (
                <Card
                  item={item}
                  query={query}
                  initialIsStarred={item.isStarred}
                  onToggle={onToggleFavorite}
                  isFavoriteVisible={isFavoriteVisible}
                  onClick={onItemClick}
                  featuredLabel={featuredLabel}
                  addToFavoritesAriaLabel={addToFavoritesAriaLabel}
                  removeFromFavoritesAriaLabel={removeFromFavoritesAriaLabel}
                  isSelected={item.id === selectedItemId}
                  className="h-full"
                  credentialsBadgeLoggedOutLabel={
                    credentialsBadgeLoggedOutLabel
                  }
                  isReadonly={isReadonly}
                  styles={{ colors: { featuredChipStyle } }}
                />
              )}
            </div>
          );
        })}
      </div>
    );
  },
)

useScrollVirtualizer = (
  itemCount: number,
  { overscan = 3, isFullWidth = false }: ScrollVirtualizerOptions = {},
): ScrollVirtualizerResult => {
  const containerRef = useRef<HTMLDivElement>(null);

  const [state, setState] = useState<VirtualizerState>(() => {
    const w = typeof window !== 'undefined' ? window.innerWidth : 1440;
    /*
     * Approximate the grid container width: available width minus the sidebar
     * (60 px on desktop) and 64 px horizontal padding (px-8 × 2), capped at
     * CONTENT_MAX_WIDTH unless the grid spans the full width.
     */
    /*
     * The sidebar renders only from the desktop boundary up — the width is
     * single-sourced from chat-shared's breakpoint constants so the grid
     * math and the layout branches agree on the band.
     */
    const sidebarWidth = w >= DESKTOP_BREAKPOINT_PX ? 60 : 0;
    const available = Math.max(0, w - sidebarWidth);
    const approxContainer =
      (isFullWidth ? available : Math.min(CONTENT_MAX_WIDTH, available)) - 64;
    const cols = getColumnCount(approxContainer);
    const rows = Math.ceil(itemCount / cols);
    return { startRow: 0, endRow: Math.min(rows, 12), columnCount: cols };
  });

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const scrollEl = getScrollParent(container.parentElement);

    const update = () => {
      const containerWidth = container.clientWidth;
      const viewportHeight = scrollEl.clientHeight;
      /*
       * Catalog keeps both views mounted. A hidden grid has zero width;
       * preserve its rows and columns so revealing it does not rebuild
       * every card from a temporary single-column layout.
       */
      if (containerWidth === 0 || viewportHeight === 0) return;

      const containerRect = container.getBoundingClientRect();
      const scrollElRect = scrollEl.getBoundingClientRect();

      const cols = getColumnCount(containerWidth);
      const rows = Math.ceil(itemCount / cols);

      // Pixels of the container that have scrolled above the viewport top.
      const scrolledPast = Math.max(0, scrollElRect.top - containerRect.top);
      const startRow = Math.max(
        0,
        Math.floor(scrolledPast / CARD_ROW_HEIGHT) - overscan,
      );
      const endRow = Math.min(
        rows,
        startRow + Math.ceil(viewportHeight / CARD_ROW_HEIGHT) + 2 * overscan,
      );

      setState((previous) =>
        previous.startRow === startRow &&
        previous.endRow === endRow &&
        previous.columnCount === cols
          ? previous
          : { startRow, endRow, columnCount: cols },
      );
    };

    scrollEl.addEventListener('scroll', update, { passive: true });
    const ro = new ResizeObserver(update);
    ro.observe(container);
    ro.observe(scrollEl);
    update();

    return () => {
      scrollEl.removeEventListener('scroll', update);
      ro.disconnect();
    };
  }, [itemCount, overscan]);

  const rowCount = Math.ceil(itemCount / state.columnCount);

  return {
    containerRef,
    startRow: state.startRow,
    endRow: state.endRow,
    columnCount: state.columnCount,
    rowCount,
    totalHeight: rowCount * CARD_ROW_HEIGHT,
  };
}

Favorites: FC<FavoritesProps> = ({
  items,
  totalCount,
  title = 'Your Favorites',
  onToggleFavorite,
  isFavoriteVisible,
  onItemClick,
  styles: favoritesStyles,
  isLeaving,
  onExitComplete,
  prevPageAriaLabel = 'Previous page',
  nextPageAriaLabel = 'Next page',
  addToFavoritesAriaLabel,
  removeFromFavoritesAriaLabel,
  selectedItemId,
  credentialsBadgeLoggedOutLabel,
}) => {
  const titleClassName =
    favoritesStyles?.typography?.titleClassName ?? 'dial-body-semi-text';

  const countClassName =
    favoritesStyles?.typography?.countClassName ?? 'dial-tiny-semi-text';

  const cssVars = buildCssVars({
    '--cat-fav-title-text': favoritesStyles?.colors?.titleText,
    '--cat-fav-count-text': favoritesStyles?.colors?.countText,
    '--cat-fav-selected-check': favoritesStyles?.colors?.selectedCheckIcon,
    '--cat-fav-selected-border': favoritesStyles?.colors?.selectedCardBorder,
    '--cat-fav-selected-bg': favoritesStyles?.colors?.selectedCardBackground,
    '--cat-fav-nav-btn': favoritesStyles?.colors?.navButton,
    '--cat-fav-nav-btn-disabled': favoritesStyles?.colors?.navButtonDisabled,
    '--cat-fav-nav-btn-hover-bg':
      favoritesStyles?.colors?.navButtonHoverBackground,
    '--cat-fav-nav-btn-active-bg':
      favoritesStyles?.colors?.navButtonActiveBackground,
    '--cat-fav-page-nav-border': favoritesStyles?.colors?.pageNavBorder,
    '--cat-fav-page-nav-bg': favoritesStyles?.colors?.pageNavBackground,
  });
  const sortedItems = useMemo(
    () =>
      [...items].sort(
        (a, b) =>
          (new Date(b.updatedAt || '').getTime() ?? 0) -
          (new Date(a.updatedAt || '').getTime() ?? 0),
      ),
    [items],
  );

  const [favPage, setFavPage] = useState(1);
  const favColumns = useFavColumns();
  const favPerPage = favColumns * FAV_ROWS;
  const favStart = (favPage - 1) * favPerPage;
  const favSlice = useMemo(
    () => sortedItems.slice(favStart, favStart + favPerPage),
    [sortedItems, favStart, favPerPage],
  );
  const favTotalPages = Math.ceil(sortedItems.length / favPerPage);
  const displayCount = totalCount ?? items.length;

  /*
   * Lock both the grid and the section to their page-1 sizes so that shorter
   * last pages don't shift the pagination or jump the section background gradient.
   * Measured after the first full-page render via useLayoutEffect (fires before
   * paint → no visible flash).
   */
  const sectionWrapperRef = useRef<HTMLDivElement>(null);
  const sectionRef = useRef<HTMLElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const [lockedGridHeight, setLockedGridHeight] = useState<
    number | undefined
  >();
  const [lockedSectionHeight, setLockedSectionHeight] = useState<
    number | undefined
  >();
  const prevColumnsRef = useRef(favColumns);

  /*
   * When the column count changes (viewport resize), go back to page 1 and
   * re-measure so the locked heights stay accurate.
   */
  useEffect(() => {
    if (prevColumnsRef.current === favColumns) return;
    prevColumnsRef.current = favColumns;
    setFavPage(1);
    setLockedGridHeight(undefined);
    setLockedSectionHeight(undefined);
  }, [favColumns]);

  /*
   * Reset to the last valid page when items are removed and the current page
   * no longer exists (e.g. deleting the only card on page 2).
   */
  useEffect(() => {
    if (favPage > favTotalPages && favTotalPages > 0) {
      setFavPage(favTotalPages);
    }
  }, [favPage, favTotalPages]);

  /*
   * Release the height lock once items reduce to a single page so the
   * section can shrink (the FLIP effect will animate the height change).
   */
  useEffect(() => {
    if (
      favTotalPages <= 1 &&
      (lockedGridHeight !== undefined || lockedSectionHeight !== undefined)
    ) {
      setLockedGridHeight(undefined);
      setLockedSectionHeight(undefined);
    }
  }, [favTotalPages, lockedGridHeight, lockedSectionHeight]);

  // Capture both heights while on the first (full) page; skip if already locked.
  useLayoutEffect(() => {
    if (
      !gridRef.current ||
      !sectionRef.current ||
      favTotalPages <= 1 ||
      favPage !== 1 ||
      lockedGridHeight !== undefined
    )
      return;
    /*
     * offsetHeight is transform-unaware; getBoundingClientRect() would return the
     * scaled value during the favFadeIn animation and produce a ~3% under-count.
     */
    setLockedGridHeight(gridRef.current.offsetHeight);
    setLockedSectionHeight(sectionRef.current.offsetHeight);
  }, [favTotalPages, favPage, lockedGridHeight]);

  /*
   * FLIP: when items are removed/added and cards shift grid positions, animate
   * them from their previous positions to their new ones. Also animates the
   * section height so the background gradient shrinks smoothly (e.g. 2 rows → 1 row).
   */
  const cardPositions = useRef<Map<string, DOMRect>>(new Map());
  const prevFavPageForFlipRef = useRef(favPage);
  const prevFavColumnsForFlipRef = useRef(favColumns);
  const prevSectionHeightRef = useRef<number>(0);
  // Guards the mount height animation from being cancelled by FLIP while it's in progress.
  const isMountAnimatingRef = useRef(false);

  useLayoutEffect(() => {
    if (!gridRef.current || isLeaving) return;

    /*
     * Clear any inline styles the mount-enter animation set on the wrapper
     * only after the mount animation has completed; clearing mid-animation
     * would cause the wrapper to jump to its natural height instantly.
     */
    if (sectionWrapperRef.current && !isMountAnimatingRef.current) {
      const w = sectionWrapperRef.current;
      w.style.height = '';
      w.style.transition = '';
    }

    const pageChanged = prevFavPageForFlipRef.current !== favPage;
    const columnsChanged = prevFavColumnsForFlipRef.current !== favColumns;
    prevFavPageForFlipRef.current = favPage;
    prevFavColumnsForFlipRef.current = favColumns;

    const cards =
      gridRef.current.querySelectorAll<HTMLElement>('[data-card-id]');
    const nextPositions = new Map<string, DOMRect>();
    cards.forEach((card) => {
      nextPositions.set(card.dataset.cardId!, getLayoutRect(card));
    });

    if (!pageChanged && !columnsChanged) {
      const section = sectionRef.current;
      const prevHeight = prevSectionHeightRef.current;

      /*
       * Measure the natural target height BEFORE any DOM mutations so that
       * offsetHeight reflects the settled layout, not a mid-animation value.
       * If a height transition is already in progress, temporarily clear the
       * inline height so the browser computes the true natural height, then
       * restore it so the ongoing transition is unaffected.
       */
      let targetHeight = 0;
      if (section) {
        const savedH = section.style.height;
        if (savedH) section.style.height = '';
        targetHeight = section.offsetHeight;
        if (savedH) section.style.height = savedH;
      }
      const heightChanged =
        section != null &&
        prevHeight > 0 &&
        Math.abs(targetHeight - prevHeight) > 2;

      /*
       * When growing, match flip duration to the section transition so cards
       * entering the new row stay in sync with the expanding boundary.
       */
      const flipDuration = targetHeight > prevHeight ? 280 : 220;
      const movers: HTMLElement[] = [];
      cards.forEach((card) => {
        const id = card.dataset.cardId!;
        const prev = cardPositions.current.get(id);
        const next = nextPositions.get(id);
        if (!prev || !next) return;

        const dx = prev.left - next.left;
        const dy = prev.top - next.top;

        /*
         * When the row count does not change, only FLIP cards that shift
         * horizontally within the same row — not cards crossing rows (those
         * only happen when height changes) and not stationary cards.
         * This avoids the jarring full-section slide on same-row adds/removes
         * while still smoothly repositioning cards displaced within a row.
         */
        if (!heightChanged && Math.abs(dy) > 0.5) return;
        if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) return;

        card.style.transition = 'none';
        card.style.transform = `translate(${dx}px, ${dy}px)`;
        movers.push(card);
      });

      if (heightChanged && section) {
        section.style.height = `${prevHeight}px`;
        section.style.overflow = 'clip';
      }

      // Single forced reflow commits all pending writes before transitions start.
      if (movers.length > 0 || heightChanged) {
        void gridRef.current.offsetHeight;
      }

      movers.forEach((card) => {
        card.style.transition = `transform ${flipDuration}ms cubic-bezier(0, 0, 0.2, 1)`;
        card.style.transform = '';
        card.addEventListener(
          'transitionend',
          () => {
            card.style.transition = '';
          },
          { once: true },
        );
      });

      if (heightChanged && section) {
        section.style.transition = 'height 280ms cubic-bezier(0, 0, 0.2, 1)';
        section.style.height = `${targetHeight}px`;

        /*
         * Use a named handler so we can remove it precisely — `once: true` is
         * unsafe here because child transitionend events bubble and would fire
         * the cleanup before the section's own height transition ends.
         */
        const handleEnd = (e: TransitionEvent) => {
          if (e.target !== section || e.propertyName !== 'height') return;
          section.style.height = '';
          section.style.overflow = '';
          section.style.transition = '';
          section.removeEventListener('transitionend', handleEnd);
        };
        section.addEventListener('transitionend', handleEnd);
      }
    }

    cardPositions.current = nextPositions;
    if (sectionRef.current) {
      const el = sectionRef.current;
      /*
       * offsetHeight returns the CSS-animated start value (not the target) at t=0 of a
       * height transition, so read the inline style.height instead when it is set — that
       * value IS the targetHeight we just applied.
       */
      const inlineH = el.style.height ? parseFloat(el.style.height) : NaN;
      prevSectionHeightRef.current = Number.isNaN(inlineH)
        ? el.offsetHeight
        : inlineH;
    }
  }, [favSlice, favPage, favColumns, isLeaving]);

  /*
   * On mount: grow from 0 → natural height so the Browse section slides down smoothly.
   * No overflow:clip — section starts at opacity:0 (sectionEnter), so clipping is unnecessary
   * and would cause the translateY(-8px) shift to clip at the wrapper's top edge.
   */
  useLayoutEffect(() => {
    const el = sectionWrapperRef.current;
    if (!el) return;
    const naturalH = el.offsetHeight;
    if (naturalH === 0) return;

    isMountAnimatingRef.current = true;
    el.style.height = '0px';
    void el.offsetHeight;
    el.style.transition = 'height 300ms cubic-bezier(0, 0, 0.2, 1)';
    el.style.height = `${naturalH}px`;

    const onEnd = (e: TransitionEvent) => {
      if (e.target !== el || e.propertyName !== 'height') return;
      clearStyles();
    };
    const clearStyles = () => {
      isMountAnimatingRef.current = false;
      // Only clear when enter completed (not if a concurrent exit already set height to 0).
      if (parseFloat(el.style.height || '0') > 0) {
        el.style.height = '';
        el.style.transition = '';
      }
      clearTimeout(fallback);
      el.removeEventListener('transitionend', onEnd);
    };
    // Fallback: clear in case transitionend is delayed (e.g. background tab).
    const fallback = setTimeout(clearStyles, 400);
    el.addEventListener('transitionend', onEnd);
    return () => {
      clearTimeout(fallback);
      el.removeEventListener('transitionend', onEnd);
    };
  }, []);

  /*
   * On exit: collapse to 0 in sync with sectionExit CSS animation so Browse slides up smoothly.
   * No overflow:clip — section fades out via sectionExit, so clipping is unnecessary.
   */
  useLayoutEffect(() => {
    if (!isLeaving || !sectionWrapperRef.current) return;
    const el = sectionWrapperRef.current;
    const currentH = el.offsetHeight;
    if (currentH === 0) return;
    el.style.height = `${currentH}px`;
    void el.offsetHeight;
    el.style.transition = 'height 260ms ease-in';
    el.style.height = '0px';
    // No cleanup needed — section is unmounted via onExitComplete after sectionExit fires.
  }, [isLeaving]);

  return (
    <div ref={sectionWrapperRef}>
      <section
        ref={sectionRef}
        className={mergeClasses(
          'flex flex-shrink-0 flex-col gap-4 pb-2 pt-2',
          styles.section,
          isLeaving && styles.sectionLeaving,
        )}
        style={{ ...cssVars, minHeight: lockedSectionHeight }}
        onAnimationEnd={(e) => {
          if (e.target === sectionRef.current && isLeaving) onExitComplete?.();
        }}
      >
        <ItemHeader
          title={title}
          postfix={displayCount}
          titleClassName={mergeClasses(titleClassName, styles.titleText)}
          postfixClassName={mergeClasses(countClassName, styles.countText)}
          trailing={
            favTotalPages > 1 ? (
              <div
                className={mergeClasses(
                  'inline-flex items-center gap-[2px] rounded-full px-[6px] py-[3px]',
                  styles.pageNav,
                )}
              >
                <button
                  aria-label={prevPageAriaLabel}
                  disabled={favPage === 1}
                  onClick={() => setFavPage((p) => p - 1)}
                  className={mergeClasses(
                    'flex size-[22px] cursor-pointer items-center justify-center rounded-full border-none bg-transparent',
                    styles.navBtn,
                  )}
                >
                  <IconChevronLeft
                    size={14}
                    className="rtl:scale-x-[-1]"
                    stroke={DIAL_KIT_ICON_STROKE}
                  />
                </button>
                <span
                  className={mergeClasses(
                    'min-w-[32px] select-none px-1 text-center',
                    countClassName,
                    styles.countText,
                  )}
                >
                  {favPage} / {favTotalPages}
                </span>
                <button
                  aria-label={nextPageAriaLabel}
                  disabled={favPage === favTotalPages}
                  onClick={() => setFavPage((p) => p + 1)}
                  className={mergeClasses(
                    'flex size-[22px] cursor-pointer items-center justify-center rounded-full border-none bg-transparent',
                    styles.navBtn,
                  )}
                >
                  <IconChevronRight
                    size={14}
                    className="rtl:scale-x-[-1]"
                    stroke={DIAL_KIT_ICON_STROKE}
                  />
                </button>
              </div>
            ) : undefined
          }
        />

        <div
          ref={gridRef}
          className={mergeClasses('grid content-start gap-5', styles.gridPage)}
          style={{
            gridTemplateColumns: `repeat(${favColumns}, minmax(0, 1fr))`,
            minHeight: lockedGridHeight,
          }}
        >
          {favSlice.map((item) => (
            <FavoriteCard
              key={`${favPage}-${item.id}`}
              item={item}
              onToggle={onToggleFavorite}
              isFavoriteVisible={isFavoriteVisible}
              onClick={onItemClick}
              addToFavoritesAriaLabel={addToFavoritesAriaLabel}
              removeFromFavoritesAriaLabel={removeFromFavoritesAriaLabel}
              isSelected={item.id === selectedItemId}
              credentialsBadgeLoggedOutLabel={credentialsBadgeLoggedOutLabel}
            />
          ))}
        </div>
      </section>
    </div>
  );
}

ListView: FC<ListViewProps> = (props) => {
  if (props.items.length === 0) {
    return (
      <div
        className={mergeClasses(
          'flex size-full flex-col items-center justify-center',
          CATALOG_CLASS.listView,
        )}
      >
        <PanelEmptyState label={props.emptyStateTitle ?? 'No results'} />
      </div>
    );
  }

  return <WindowedListView {...props} />;
}

FavoriteCard: FC<FavoriteCardProps> = ({
  item,
  initialIsStarred = true,
  onToggle,
  isFavoriteVisible,
  onClick,
  nameClassName,
  colors,
  versionClassName,
  lastUsedClassName,
  query,
  addToFavoritesAriaLabel = 'Add to favorites',
  removeFromFavoritesAriaLabel = 'Remove from favorites',
  isSelected = false,
  credentialsBadgeLoggedOutLabel,
}) => {
  const [isStarred, setIsStarred] = useState(initialIsStarred);
  const [isLeaving, setIsLeaving] = useState(false);

  const handleToggle = (e: MouseEvent<HTMLElement>) => {
    e.stopPropagation();
    const next = !isStarred;
    setIsStarred(next);
    if (!next) {
      setIsLeaving(true);
    } else {
      onToggle?.(item.id, next);
    }
  };

  const handleClick = onClick && !isLeaving ? () => onClick(item) : undefined;

  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLElement>) => {
      if (!onClick || isLeaving) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onClick(item);
      }
    },
    [onClick, item, isLeaving],
  );

  return (
    <CardShell
      data-card-id={item.id}
      role={handleClick != null ? 'button' : undefined}
      tabIndex={handleClick != null ? 0 : undefined}
      aria-label={item.name}
      className={mergeClasses(
        'box-border min-w-0 cursor-pointer flex-row items-start gap-1 text-start',
        isLeaving && styles.cardLeaving,
        isSelected && styles.selectedCard,
        CATALOG_CLASS.favoriteCard,
      )}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      onAnimationEnd={
        isLeaving
          ? (e) => {
              if (e.currentTarget === e.target) onToggle?.(item.id, false);
            }
          : undefined
      }
    >
      {isSelected && (
        <IconCheck
          size={DIAL_ICON_SIZE.SM}
          className={mergeClasses(
            'absolute end-3 top-3 shrink-0',
            styles.selectedCheck,
          )}
          aria-hidden
          stroke={DIAL_KIT_ICON_STROKE}
        />
      )}

      <div className="flex min-w-0 flex-1 flex-col items-start gap-1">
        <AppIdentity
          icon={item.iconUrl}
          type={item.type}
          name={item.name}
          version={item.version}
          lastUsed={item.lastUsed}
          size={DeploymentSize.LG}
          query={query}
          className="min-w-0 self-stretch"
          styles={{
            colors,
            typography: {
              nameClassName,
              versionClassName,
              lastUsedClassName,
            },
          }}
          iconOverlay={
            <CredentialsBadge
              credentials={item.credentials}
              loggedOutLabel={credentialsBadgeLoggedOutLabel}
            />
          }
        />
      </div>
      {isFavoriteVisible?.(item) !== false && (
        <StarToggleButton
          isStarred={isStarred}
          size={ElementSize.Small}
          onClick={handleToggle}
          ariaLabel={
            isStarred ? removeFromFavoritesAriaLabel : addToFavoritesAriaLabel
          }
          className="self-end"
        />
      )}
    </CardShell>
  );
}

